def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - represents one quote
                        field += '"'
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        # Check what follows
                        if i < len(line) and line[i] != ',':
                            # Closing quote not followed by comma or end of line
                            return None
                        if i < len(line):
                            # Skip the comma
                            i += 1
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None
            fields.append(field)
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is malformed
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            if i < len(line):
                # Skip the comma
                i += 1

    return fields

